#include <iostream>
#include <random>
#include <vector>
#include <algorithm>
int main() {
    std::mt19937 a(2026), b(2026);
    std::uniform_int_distribution<int> da(-3, 3), db(-3, 3);
    std::vector<int> x, y;
    for (int i = 0; i < 512; ++i) {
        x.push_back(da(a));
        y.push_back(db(b));
    }
    bool bounded = std::all_of(x.begin(), x.end(),
                               [](int n) { return n >= -3 && n <= 3; });
    std::cout << (x == y) << ' ' << bounded << ' ' << x.size() << '\n';
}

